'use strict';

var concat = require( './../lib' );

var out = concat( 'hello', 'world' );
console.log( out );
// => 'helloworld'

out = concat( 'john', 'doe' );
console.log( out );
// => 'johndoe'

out = concat( 'stdlib', 'isawesome' );
console.log( out );
// => 'stdlibisawesome'

out = concat( '$**_Beep_BoOp_**$', '!!!' );
console.log( out );
// => '$**_Beep_BoOp_**$!!!'

out = concat( '', 'empty' );
console.log( out );
// => 'empty'
